package ru.ryadom.calendar;
import android.content.*;import org.json.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
final class Mirror {
 static String hash(String value){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 static String fingerprint(Event e){return hash(e.title+"\u0000"+e.description+"\u0000"+e.location+"\u0000"+e.start+"|"+e.end+"|"+e.allDay+"|"+e.reminderMinutes);}
 static String calendarKey(String source,String cal){return source+"|"+cal;}
 static JSONObject role(JSONObject data,String key){JSONObject value=Store.object(data,"calendarRoles").optJSONObject(key);return value==null?new JSONObject():value;}
 static boolean satellite(JSONObject data,String key){return "satellite".equals(role(data,key).optString("role","primary"));}
 static Event payload(Event original,String source,String calendar,boolean anonymous,String token)throws Exception{Event e=Event.from(original.json());e.source=source;e.calendar=calendar;e.id="";e.stableId="";e.etag="";e.remoteUri="";e.title=anonymous?"Занят":original.title;e.description=anonymous?"":original.description;e.location=anonymous?"":original.location;e.reminderMinutes=-1;e.copyToken=token;e.recurring=false;return e;}
 static Map<String,JSONObject> accounts(JSONObject data){Map<String,JSONObject> out=new LinkedHashMap<>();JSONArray arr=Store.array(data,"accounts");for(int i=0;i<arr.length();i++){JSONObject a=arr.optJSONObject(i);out.put(a.optString("id"),a);}return out;}
 static boolean healthy(JSONObject data,String source){JSONObject s=Store.object(data,"statuses").optJSONObject(source);JSONObject a=accounts(data).get(source);return a!=null&&a.optBoolean("active",true)&&s!=null&&s.optLong("success")>0&&s.optString("error").isEmpty();}
 static boolean isCopy(JSONObject data,Event e){if(!e.copyToken.isEmpty())return true;JSONObject links=Store.object(data,"mirrorLinks");Iterator<String> it=links.keys();while(it.hasNext()){JSONObject dest=links.optJSONObject(it.next()).optJSONObject("target");if(dest!=null){Event target=Event.from(dest);if(target.source.equals(e.source)&&(!target.stableId.isEmpty()?target.stableId.equals(e.stableId):target.id.equals(e.id)))return true;}}return false;}
 interface Writer {Event save(Context c,JSONObject a,String calendar,Event before,Event desired,String token)throws Exception;void delete(Context c,JSONObject a,Event e)throws Exception;}
 static final Writer LIVE=new Writer(){public Event save(Context c,JSONObject a,String cal,Event old,Event e,String token)throws Exception{return EventWrites.save(c,a,cal,old,e,token);}public void delete(Context c,JSONObject a,Event e)throws Exception{EventWrites.delete(c,a,e);}};
 static void run(Context c,Sync.DeletionChecker checker){run(c,checker,LIVE);}
 static void run(Context c,Sync.DeletionChecker checker,Writer writer){String warning="";int changed=0;Set<String> failedTargets=new HashSet<>();try{
  JSONObject data=Store.read(c);Map<String,JSONObject> accounts=accounts(data);Map<String,Event> originals=new LinkedHashMap<>();JSONArray all=Store.array(data,"events");for(int i=0;i<all.length();i++){Event e=Event.from(all.getJSONObject(i));if(!isCopy(data,e))originals.put(e.source+"|"+(e.stableId.isEmpty()?e.id:e.stableId),e);}
  Map<String,JSONObject> wanted=new LinkedHashMap<>();for(Map.Entry<String,Event> entry:originals.entrySet()){Event e=entry.getValue();String origin=calendarKey(e.source,e.calendar);JSONObject account=accounts.get(e.source);if(account==null||!satellite(data,origin)||e.isCancelled(account.optString("type")))continue;
   for(JSONObject a:accounts.values()){String targetSource=a.optString("id");JSONObject status=Store.object(data,"statuses").optJSONObject(targetSource),calendars=status==null?null:status.optJSONObject("calendars");if(calendars==null)continue;Iterator<String> keys=calendars.keys();while(keys.hasNext()){String cal=keys.next(),destination=calendarKey(targetSource,cal);if(origin.equals(destination)||satellite(data,destination))continue;if("device".equals(account.optString("type"))&&"device".equals(a.optString("type"))&&cal.equals(e.calendar))continue;String token="copy-"+hash(entry.getKey()+"\u0000"+destination);wanted.put(token,new JSONObject().put("original",e.json()).put("sourceIdentity",entry.getKey()).put("targetSource",targetSource).put("targetCalendar",cal));}}
  }
  for(Map.Entry<String,JSONObject> item:wanted.entrySet()){String token=item.getKey();JSONObject route=item.getValue();Event original=Event.from(route.getJSONObject("original"));String destination=route.getString("targetSource"),cal=route.getString("targetCalendar");if(failedTargets.contains(destination))continue;if(changed>=30){warning="Часть копий ожидает следующего обновления.";break;}if(!healthy(data,original.source)||!healthy(data,destination)){warning="Копирование ожидает успешного обновления источников.";continue;}JSONObject link=Store.object(Store.read(c),"mirrorLinks").optJSONObject(token);Event before=link==null||!link.has("target")?null:Event.from(link.getJSONObject("target"));boolean anonymous=role(data,calendarKey(original.source,original.calendar)).optBoolean("anonymous",true);
   try{if(!anonymous&&writer==LIVE)original=EventWrites.detail(c,accounts.get(original.source),original);Event desired=payload(original,destination,cal,anonymous,token);String signature=fingerprint(desired);if(link!=null&&signature.equals(link.optString("fingerprint"))&&before!=null)continue;
    JSONObject pending=route; if(before!=null)pending.put("target",before.json());Store.edit(c,d->{JSONObject links=Store.object(d,"mirrorLinks");links.put(token,pending);d.put("mirrorLinks",links);});
    // Refresh target version from the successful snapshot when available.
    if(before!=null)for(int j=0;j<all.length();j++){Event current=Event.from(all.getJSONObject(j));if(current.source.equals(before.source)&&((!current.copyToken.isEmpty()&&current.copyToken.equals(token))||current.id.equals(before.id))){before=current;break;}}
    Event saved=writer.save(c,accounts.get(destination),cal,before,desired,token);saved.copyToken=token;pending.put("target",saved.json()).put("fingerprint",signature);Store.edit(c,d->Store.object(d,"mirrorLinks").put(token,pending));changed++;
   }catch(Exception error){failedTargets.add(destination);warning=error instanceof Providers.Failure?error.getMessage():"Копирование не завершено; повторим при обновлении.";}
  }
  JSONObject links=Store.object(Store.read(c),"mirrorLinks");Iterator<String> keys=links.keys();while(keys.hasNext()){String token=keys.next();if(wanted.containsKey(token))continue;if(changed>=30){warning="Часть копий ожидает следующего обновления.";break;}JSONObject link=links.getJSONObject(token);Event old=Event.from(link.getJSONObject("original"));if(!healthy(data,old.source)||!healthy(data,link.optString("targetSource")))continue;JSONObject target=link.optJSONObject("target");if(target==null){try{if(writer!=LIVE){warning="Неподтверждённая запись ожидает восстановления связи.";continue;}Event recovered=EventWrites.recover(c,accounts.get(link.optString("targetSource")),link.optString("targetCalendar"),token);if(recovered==null){Store.edit(c,d->Store.object(d,"mirrorLinks").remove(token));continue;}target=recovered.json();final JSONObject recoveredJson=target;Store.edit(c,d->Store.object(d,"mirrorLinks").getJSONObject(token).put("target",recoveredJson));}catch(Exception error){warning="Не удалось проверить неподтверждённую копию.";continue;}}try{Event current=originals.get(link.optString("sourceIdentity"));boolean routeRemoved=!satellite(data,calendarKey(old.source,old.calendar))||satellite(data,calendarKey(link.optString("targetSource"),link.optString("targetCalendar")));boolean cancelled=current!=null&&current.isCancelled(accounts.get(old.source).optString("type"));if(!routeRemoved&&!cancelled){if(current!=null)continue; // Missing from a window is not proof of deletion.
      if(!checker.deleted(c,accounts.get(old.source),old))continue;}
     Event dest=Event.from(target);for(int j=0;j<all.length();j++){Event candidate=Event.from(all.getJSONObject(j));if(candidate.source.equals(dest.source)&&candidate.id.equals(dest.id)){dest=candidate;break;}}writer.delete(c,accounts.get(dest.source),dest);Store.edit(c,d->Store.object(d,"mirrorLinks").remove(token));changed++;
    }catch(Exception error){warning=error instanceof Providers.Failure?error.getMessage():"Удаление копии не подтверждено; повторим позже.";}}
 }catch(Exception error){warning="Синхронизация копий не завершена.";}final String status=warning.isEmpty()?"Копии синхронизированы":warning;final int count=changed;Store.edit(c,d->d.put("mirrorStatus",status).put("mirrorChanged",count));}
}
